            precond_apply(p, V + j * n, Z + j * n);
            spmv(A, Z + j * n, w);

            for (int i = 0; i <= j; i++) {
                double h = dot(n, w, V + i * n);
                H[i * restart + j] = h;
                for (int k = 0; k < n; k++) w[k] -= h * V[i * n + k];
