            H[j * restart + j] = rot;
            H[(j + 1) * restart + j] = 0.0;

            double gtemp = cs[j] * g[j] + sn[j] * g[j + 1];
            g[j + 1] = -sn[j] * g[j] + cs[j] * g[j + 1];
